-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (10566, 38, 'Versicherungsfremde Leistungen (v. a. Bürgergeld-Beiträge) kostendeckend aus Steuermitteln finanzieren (Bund)', 'Laut IGES deckt die Bürgergeld-Pauschale nur rund 39 % der Kosten (Lücke ca. 9-10 Mrd. Euro), Erstattung senkt den Beitragsbedarf spürbar. Dagegen: einmalige Entlastung ohne Wirkung auf das Ausgabenwachstum, belastet den angespannten Bundeshaushalt.', 'belegt', 'https://www.haufe.de/sozialwesen/gesundheitsausgaben-fuer-buergergeldbeziehende-nicht-gedeckt_244_623712.html', 'bund', null, true, 'blind'),
  (10567, 38, 'Privatversicherte in eine gemeinsame Bürgerversicherung einbeziehen (Bund)', 'IGES/Bertelsmann-Simulation: Einbeziehung aller Privatversicherten senkt den Beitragssatz um 0,2-0,6 Punkte, weil sie im Schnitt mehr verdienen und gesünder sind. Dagegen: einmaliger Effekt, verfassungsrechtliche Fragen zum PKV-Bestand, lange Übergänge.', 'belegt', 'https://idw-online.de/de/news731604', 'bund', null, true, 'blind'),
  (10568, 38, 'Beitragsbemessungsgrenze anheben oder abschaffen und weitere Einkommensarten verbeitragen (Bund)', 'Modellrechnungen zeigen Mehreinnahmen und Beitragssatzspielraum durch breitere Einnahmebasis. Dagegen: bremst das Ausgabenwachstum nicht, Erhebung auf Kapitaleinkünfte aufwendig, mögliche Ausweichreaktionen und Belastung von Arbeitskosten umstritten.', 'gemischt', null, 'bund', null, true, 'blind'),
  (10569, 38, 'Beitragsbemessung für geringverdienende Selbstständige an tatsächlichen Einnahmen ausrichten (Bund)', 'Senkt die Beitragslast geringverdienender Selbstständiger und macht Beiträge für sie bezahlbarer. Dagegen: betrifft eine kleine Gruppe, mindert eher die Einnahmen und ändert nichts am allgemeinen Beitragsanstieg.', 'offen', null, 'bund', null, true, 'blind'),
  (10570, 38, 'Fallpauschalen im Krankenhaus abschaffen und Betriebskosten voll bzw. über Budgets finanzieren (Bund)', 'Könnte Fehlanreize zur Mengenausweitung verringern. Dagegen: volle Kostenerstattung bzw. Selbstkostendeckung schwächt Kostenkontrolle und dürfte die Ausgaben der Kassen erhöhen; Erfahrungen vor 1993 zeigten steigende Kosten.', 'gemischt', null, 'bund', null, true, 'blind'),
  (10571, 38, 'Krankenhausstrukturen spezialisieren und Krankenhausreform umsetzen (Bund)', 'Konzentration kann Vorhaltekosten und Doppelstrukturen senken und Qualität verbessern. Dagegen: Einsparungen erst langfristig und unsicher, Umbau verursacht zunächst hohe Transformationskosten.', 'gemischt', null, 'bund', null, true, 'blind'),
  (10572, 38, 'Krankenhausinvestitionen und Transformationskosten aus anderen Mitteln statt aus GKV-Beiträgen tragen (Bund)', 'Entlastet die Beitragszahler von Kosten, die nicht aus dem laufenden Betrieb stammen, und mindert Quersubventionierung aus Fallerlösen. Dagegen: geringer, kaum untersuchter Effekt auf den Beitragssatz; Finanzierung durch Länder bzw. PKV ungeklärt.', 'offen', null, 'bund', null, true, 'blind'),
  (10573, 38, 'Ärztliche Honorare im ambulanten Bereich erhöhen und Budgetierung aufheben (Bund)', 'Kann die Versorgung in Praxen stärken. Dagegen: setzt bei den Ausgaben an, erhöht sie aber und treibt damit den Beitragsbedarf; für bezahlbare Beiträge kein Beitrag.', 'offen', null, 'bund', null, true, 'blind'),
  (10574, 38, 'Primärarztsystem mit hausärztlicher Steuerung einführen (Bund)', 'Systematische Übersicht: Gatekeeping senkt Facharzt- und Klinikinanspruchnahme und teils die Ausgaben bei besserer Qualität. Dagegen: Evidenz schwach und meist aus anderen Systemen, geringere Patientenzufriedenheit, Hausarztmangel.', 'gemischt', 'https://blogs.imperial.ac.uk/medical-centre/?p=434', 'bund', null, true, 'blind'),
  (10575, 38, 'Leistungen ohne Nutzennachweis abbauen, etwa über Zweitmeinungen und Prüfung des Leistungskatalogs (Bund)', 'Abbau von Über- und Fehlversorgung kann Ausgaben dämpfen. Dagegen: Wirkung deutscher Zweitmeinungsverfahren kaum belegt, Inanspruchnahme sehr gering; Streichungen sind langwierig und bringen meist wenig Volumen.', 'offen', null, 'bund', null, true, 'blind'),
  (10576, 38, 'Zahnersatz und Sehhilfen vollständig in den GKV-Leistungskatalog aufnehmen (Bund)', 'Senkt hohe Eigenanteile deutlich; Kostenbeteiligung mindert nachweislich auch nötige Inanspruchnahme, vor allem bei Geringverdienenden. Dagegen: Mehrausgaben in Milliardenhöhe erhöhen den Beitragsbedarf, Finanzierung ungeklärt.', 'belegt', 'https://en.wikipedia.org/wiki/RAND_Health_Insurance_Experiment', 'bund', null, true, 'blind')
