insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (10577, 38, 11, null, 'Mehr Effizienz beim Einsatz der Beitragsgelder in der gesetzlichen Krankenversicherung, mehr Wettbewerb der Krankenkassen.', '{3801}', null, 1, 2, null, 'Mehr Effizienz und Kassenwettbewerb können Ausgaben dämpfen. Dagegen: ohne konkrete Instrumente unbestimmt, Wirkung des Kassenwettbewerbs auf Leistungsausgaben gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10578, 38, 12, null, 'Versicherungsfremde Aufgaben im Gesundheitswesen aus Steuermitteln finanzieren', '{3802}', 10566, 2, 2, null, 'Laut IGES deckt die Bürgergeld-Pauschale nur rund 39 % der Kosten (Lücke ca. 9-10 Mrd. Euro), Erstattung senkt den Beitragsbedarf spürbar. Dagegen: einmalige Entlastung ohne Wirkung auf das Ausgabenwachstum, belastet den angespannten Bundeshaushalt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', 'https://www.haufe.de/sozialwesen/gesundheitsausgaben-fuer-buergergeldbeziehende-nicht-gedeckt_244_623712.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10579, 38, 12, null, 'Krankenkassen und private Versicherungen in einem solidarischen System zusammenführen', '{3801}', 10567, 2, 1, null, 'IGES/Bertelsmann-Simulation: Einbeziehung aller Privatversicherten senkt den Beitragssatz um 0,2-0,6 Punkte, weil sie im Schnitt mehr verdienen und gesünder sind. Dagegen: einmaliger Effekt, verfassungsrechtliche Fragen zum PKV-Bestand, lange Übergänge.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', 'https://idw-online.de/de/news731604', 'belegt', '2026-10-21', false, true, 'blind'),
  (10580, 38, 12, null, 'Finanzausgleich zwischen Krankenkassen gerechter gestalten und private Versicherungen einbeziehen', '{3801}', null, 1, 1, null, 'Einbeziehung der PKV in den Risikostrukturausgleich brächte der GKV zusätzliche Mittel. Dagegen: verfassungsrechtlich umstritten, und ein gerechterer Ausgleich zwischen Kassen verteilt Geld nur um.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10581, 38, 12, null, 'Beiträge stärker an der wirtschaftlichen Leistungsfähigkeit der Versicherten ausrichten', '{3801}', null, 1, 2, null, 'Kann Beiträge für Geringverdienende bezahlbarer machen. Dagegen: ohne Angabe des Wegs unbestimmt, ändert am Ausgabenwachstum nichts.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=29', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10582, 38, 12, null, 'Budgets für Hausärztinnen und Hausärzte abschaffen', '{3801}', 10573, 0, 3, null, 'Kann die Versorgung in Praxen stärken. Dagegen: setzt bei den Ausgaben an, erhöht sie aber und treibt damit den Beitragsbedarf; für bezahlbare Beiträge kein Beitrag.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10583, 38, 12, null, 'Begrenzung finanzieller Belastungen der Versicherten als Teil der Sicherheit im Gesundheitswesen', '{3804}', null, 1, 2, null, 'Zielt auf geringere Zuzahlungen und Eigenanteile. Dagegen: weder Instrument noch Umfang genannt, Wirkung daher kaum abschätzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10584, 38, 13, null, 'Beitragsbemessung reformieren und auch Kapitaleinnahmen zur Finanzierung heranziehen', '{3801}', 10568, 2, 2, null, 'Modellrechnungen zeigen Mehreinnahmen und Beitragssatzspielraum durch breitere Einnahmebasis. Dagegen: bremst das Ausgabenwachstum nicht, Erhebung auf Kapitaleinkünfte aufwendig, mögliche Ausweichreaktionen und Belastung von Arbeitskosten umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10585, 38, 13, null, 'Umsetzung der Krankenhausreform vorantreiben, gemeinsam mit den Ländern', '{3801}', 10571, 1, 2, null, 'Konzentration kann Vorhaltekosten und Doppelstrukturen senken und Qualität verbessern. Dagegen: Einsparungen erst langfristig und unsicher, Umbau verursacht zunächst hohe Transformationskosten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=89', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10586, 38, 13, null, 'Fehl- und Überversorgung abbauen, unter anderem durch mehr Zweitmeinungsverfahren', '{3801}', 10575, 1, 2, null, 'Abbau von Über- und Fehlversorgung kann Ausgaben dämpfen. Dagegen: Wirkung deutscher Zweitmeinungsverfahren kaum belegt, Inanspruchnahme sehr gering; Streichungen sind langwierig und bringen meist wenig Volumen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10587, 38, 13, null, 'Abrechnungsbetrug und Fehlverhalten im Gesundheitswesen wirkungsvoller begrenzen', '{3801}', null, 1, 3, null, 'Bessere Betrugsbekämpfung holt Geld zurück und ist rechtlich einfach. Dagegen: aufgedeckte Schäden machen nur einen kleinen Teil der Ausgaben aus, Wirkung auf den Beitragssatz gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10588, 38, 13, null, 'Hausärztlich-zentrierte Primärversorgung stärken, für bessere Qualität und Effizienz', '{3801}', 10574, 2, 2, null, 'Systematische Übersicht: Gatekeeping senkt Facharzt- und Klinikinanspruchnahme und teils die Ausgaben bei besserer Qualität. Dagegen: Evidenz schwach und meist aus anderen Systemen, geringere Patientenzufriedenheit, Hausarztmangel.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=88', 'https://blogs.imperial.ac.uk/medical-centre/?p=434', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10589, 38, 13, null, 'Mindestbemessungsgrenze in der Krankenversicherung für Soloselbstständige reformieren', '{3801}', 10569, 1, 3, null, 'Senkt die Beitragslast geringverdienender Selbstständiger und macht Beiträge für sie bezahlbarer. Dagegen: betrifft eine kleine Gruppe, mindert eher die Einnahmen und ändert nichts am allgemeinen Beitragsanstieg.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10590, 38, 13, null, 'Private Versicherungen an den Transformationskosten der Krankenhäuser beteiligen', '{3801}', 10572, 1, 2, null, 'Entlastet die Beitragszahler von Kosten, die nicht aus dem laufenden Betrieb stammen, und mindert Quersubventionierung aus Fallerlösen. Dagegen: geringer, kaum untersuchter Effekt auf den Beitragssatz; Finanzierung durch Länder bzw. PKV ungeklärt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=89', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10591, 38, 13, null, 'Versicherungsfremde Leistungen über den Staat finanzieren, etwa Rentenbeiträge pflegender Angehöriger und Beiträge für Bürgergeldbeziehende', '{3802}', 10566, 2, 2, null, 'Laut IGES deckt die Bürgergeld-Pauschale nur rund 39 % der Kosten (Lücke ca. 9-10 Mrd. Euro), Erstattung senkt den Beitragsbedarf spürbar. Dagegen: einmalige Entlastung ohne Wirkung auf das Ausgabenwachstum, belastet den angespannten Bundeshaushalt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=93', 'https://www.haufe.de/sozialwesen/gesundheitsausgaben-fuer-buergergeldbeziehende-nicht-gedeckt_244_623712.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10592, 38, 14, null, 'Ausgabenwachstum der GKV soll nicht stärker steigen als die Einnahmen.', '{3801}', null, 2, 2, null, 'Bindung der Ausgaben an die Einnahmen ist Kernempfehlung der Finanzkommission und setzt direkt am Ausgabenwachstum an. Dagegen: frühere Budgetierungen wirkten nur zeitweise und können Versorgungsengpässe auslösen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10593, 38, 14, null, 'Leistungsausweitungen der letzten zehn Jahre prüfen; nicht bewährte Leistungen aus dem Leistungskatalog streichen.', '{3801}', 10575, 1, 2, null, 'Abbau von Über- und Fehlversorgung kann Ausgaben dämpfen. Dagegen: Wirkung deutscher Zweitmeinungsverfahren kaum belegt, Inanspruchnahme sehr gering; Streichungen sind langwierig und bringen meist wenig Volumen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10594, 38, 14, null, 'Ungekürzte, leistungsgerechte Vergütung aller Gesundheitsberufe in der ambulanten Versorgung.', '{3801}', 10573, 0, 3, null, 'Kann die Versorgung in Praxen stärken. Dagegen: setzt bei den Ausgaben an, erhöht sie aber und treibt damit den Beitragsbedarf; für bezahlbare Beiträge kein Beitrag.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10595, 38, 14, null, 'Krankenhausversorgung spezialisieren und die Kostenentwicklung bremsen.', '{3801}', 10571, 1, 2, null, 'Konzentration kann Vorhaltekosten und Doppelstrukturen senken und Qualität verbessern. Dagegen: Einsparungen erst langfristig und unsicher, Umbau verursacht zunächst hohe Transformationskosten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10596, 38, 14, null, 'Primärarztsystem in der ambulanten Versorgung: Haus- und Kinderärzte als erste Anlaufstelle.', '{3801}', 10574, 2, 2, null, 'Systematische Übersicht: Gatekeeping senkt Facharzt- und Klinikinanspruchnahme und teils die Ausgaben bei besserer Qualität. Dagegen: Evidenz schwach und meist aus anderen Systemen, geringere Patientenzufriedenheit, Hausarztmangel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', 'https://blogs.imperial.ac.uk/medical-centre/?p=434', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10597, 38, 14, null, 'Besondere Vergütung für Arzneimittel mit Therapieerfolgen.', '{3801}', null, 1, 2, null, 'Erfolgsabhängige Vergütung kann Zahlungen für unwirksame Arzneimittel vermeiden. Dagegen: Messung aufwendig, Einsparungen in Studien uneinheitlich, als Zusatzvergütung eher ausgabensteigernd.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10598, 38, 14, null, 'Krankenkassen sollen für vorsorgende Versicherte einen reduzierten Zusatzbeitrag einführen können.', '{3801}', null, 1, 2, null, 'Anreize zur Vorsorge können langfristig Krankheitskosten senken. Dagegen: Einsparungen durch Bonusmodelle sind kaum belegt, Mitnahmeeffekte bei ohnehin Gesunden mindern die Einnahmen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10599, 38, 14, null, 'Beiträge für Selbstständige in der GKV an den tatsächlichen Einnahmen orientieren.', '{3801}', 10569, 1, 3, null, 'Senkt die Beitragslast geringverdienender Selbstständiger und macht Beiträge für sie bezahlbarer. Dagegen: betrifft eine kleine Gruppe, mindert eher die Einnahmen und ändert nichts am allgemeinen Beitragsanstieg.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=19', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10600, 38, 15, null, 'Fallpauschalen im Krankenhaus abschaffen, mittelfristig individuelle Budgetvereinbarungen', '{3801}', 10570, 0, 2, null, 'Könnte Fehlanreize zur Mengenausweitung verringern. Dagegen: volle Kostenerstattung bzw. Selbstkostendeckung schwächt Kostenkontrolle und dürfte die Ausgaben der Kassen erhöhen; Erfahrungen vor 1993 zeigten steigende Kosten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10601, 38, 15, null, 'Ende der Behandlung ohne Vergütungsanspruch in der ambulanten ärztlichen Versorgung', '{3801}', 10573, 0, 3, null, 'Kann die Versorgung in Praxen stärken. Dagegen: setzt bei den Ausgaben an, erhöht sie aber und treibt damit den Beitragsbedarf; für bezahlbare Beiträge kein Beitrag.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10602, 38, 15, null, 'Gestaffelte Bonus- und Rückvergütungssysteme gegen Bagatellbehandlungen', '{3801}', null, 1, 2, null, 'Finanzielle Anreize senken nachweislich die Inanspruchnahme (RAND-Experiment). Dagegen: es entfällt auch nötige Versorgung, besonders bei Geringverdienenden; die Einsparung für die Kassen ist begrenzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10603, 38, 15, null, 'Bürgergeld-Mitversicherung in der Krankenversicherung vollständig aus dem Bundeshaushalt finanzieren', '{3802}', 10566, 2, 2, null, 'Laut IGES deckt die Bürgergeld-Pauschale nur rund 39 % der Kosten (Lücke ca. 9-10 Mrd. Euro), Erstattung senkt den Beitragsbedarf spürbar. Dagegen: einmalige Entlastung ohne Wirkung auf das Ausgabenwachstum, belastet den angespannten Bundeshaushalt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=22', 'https://www.haufe.de/sozialwesen/gesundheitsausgaben-fuer-buergergeldbeziehende-nicht-gedeckt_244_623712.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10604, 38, 16, null, 'Beitragsbemessungsgrenze in der Krankenversicherung abschaffen; Beiträge auf alle Einkommen erheben, auch auf Kapitalerträge.', '{3801}', 10568, 2, 2, null, 'Modellrechnungen zeigen Mehreinnahmen und Beitragssatzspielraum durch breitere Einnahmebasis. Dagegen: bremst das Ausgabenwachstum nicht, Erhebung auf Kapitaleinkünfte aufwendig, mögliche Ausweichreaktionen und Belastung von Arbeitskosten umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10605, 38, 16, null, 'Gesetzliche Krankenversicherung soll alle medizinisch sinnvollen Leistungen abdecken, etwa Zahnersatz und Brillen; nutzlose Leistungen sollen gestrichen werden.', '{3801,3804}', null, 2, 1, null, 'Übernahme von Zahnersatz und Brillen senkt Eigenanteile deutlich, Streichung nutzloser Leistungen dämpft Ausgaben. Dagegen: Mehrausgaben übersteigen absehbar die Einsparungen, Finanzierung ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10606, 38, 16, null, 'Betriebskosten der Krankenhäuser vollständig von den Krankenkassen finanzieren; Fallpauschalen abschaffen.', '{3801}', 10570, 0, 2, null, 'Könnte Fehlanreize zur Mengenausweitung verringern. Dagegen: volle Kostenerstattung bzw. Selbstkostendeckung schwächt Kostenkontrolle und dürfte die Ausgaben der Kassen erhöhen; Erfahrungen vor 1993 zeigten steigende Kosten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'gemischt', '2026-10-21', false, true, 'blind'),
  (10607, 38, 16, null, 'Arzneimittelpreise in der EU einheitlich festlegen, um den Preisanstieg bei Arzneimitteln zu begrenzen.', '{3801}', null, 1, 1, null, 'Gemeinsame Preisfestsetzung könnte die Verhandlungsmacht gegenüber Herstellern stärken. Dagegen: hängt von EU-Entscheidungen ab, und einheitliche Preise könnten für Deutschland auch höher ausfallen als heute.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10608, 38, 16, null, 'Bund und Länder sollen nachhaltig in die Krankenhäuser investieren.', '{3801}', 10572, 1, 2, null, 'Entlastet die Beitragszahler von Kosten, die nicht aus dem laufenden Betrieb stammen, und mindert Quersubventionierung aus Fallerlösen. Dagegen: geringer, kaum untersuchter Effekt auf den Beitragssatz; Finanzierung durch Länder bzw. PKV ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10609, 38, 17, null, 'Bürgerversicherung mit Einzahlung nach Einkommen einführen und Zusatzbeiträge abschaffen', '{3801}', 10567, 2, 1, null, 'IGES/Bertelsmann-Simulation: Einbeziehung aller Privatversicherten senkt den Beitragssatz um 0,2-0,6 Punkte, weil sie im Schnitt mehr verdienen und gesünder sind. Dagegen: einmaliger Effekt, verfassungsrechtliche Fragen zum PKV-Bestand, lange Übergänge.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=26', 'https://idw-online.de/de/news731604', 'belegt', '2026-10-21', false, true, 'blind'),
  (10610, 38, 17, null, 'Grundfreibetrag auf Sozialabgaben, gegenfinanziert durch höhere Beitragsbemessungsgrenzen', '{3801}', null, 1, 2, null, 'Freibetrag entlastet Geringverdienende, Anhebung der Bemessungsgrenze verbreitert die Einnahmebasis. Dagegen: als Gegenfinanzierung angelegt, also für die Kasse etwa aufkommensneutral; Ausgabenwachstum bleibt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10611, 38, 17, null, 'Hausärzte als Ansprechpartner höher vergüten', '{3801}', 10573, 0, 3, null, 'Kann die Versorgung in Praxen stärken. Dagegen: setzt bei den Ausgaben an, erhöht sie aber und treibt damit den Beitragsbedarf; für bezahlbare Beiträge kein Beitrag.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10612, 38, 17, null, 'Abschaffung der Trennung der Versorgungssektoren (ambulant, Pflege, stationär)', '{3801}', null, 1, 1, null, 'Bessere Verzahnung der Sektoren kann Doppeluntersuchungen und unnötige Klinikaufenthalte vermeiden. Dagegen: völlige Abschaffung der Sektorentrennung ist unbestimmt, berührt Länderkompetenzen und Einsparungen sind kaum belegt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10613, 38, 17, null, 'Zahnersatz und Sehhilfen wieder vollständig in den Leistungskatalog der gesetzlichen Krankenversicherung aufnehmen', '{3804}', 10576, 2, 1, null, 'Senkt hohe Eigenanteile deutlich; Kostenbeteiligung mindert nachweislich auch nötige Inanspruchnahme, vor allem bei Geringverdienenden. Dagegen: Mehrausgaben in Milliardenhöhe erhöhen den Beitragsbedarf, Finanzierung ungeklärt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', 'https://en.wikipedia.org/wiki/RAND_Health_Insurance_Experiment', 'belegt', '2026-10-21', false, true, 'blind'),
  (10614, 38, 17, null, 'Gesetzliche Krankenkassen finanzieren versicherungsfremde Leistungen aus Steuermitteln', '{3802}', 10566, 2, 2, null, 'Laut IGES deckt die Bürgergeld-Pauschale nur rund 39 % der Kosten (Lücke ca. 9-10 Mrd. Euro), Erstattung senkt den Beitragsbedarf spürbar. Dagegen: einmalige Entlastung ohne Wirkung auf das Ausgabenwachstum, belastet den angespannten Bundeshaushalt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=26', 'https://www.haufe.de/sozialwesen/gesundheitsausgaben-fuer-buergergeldbeziehende-nicht-gedeckt_244_623712.html', 'belegt', '2026-10-21', false, true, 'blind');

